namespace Payments;

public sealed class PaymentGateway
{
    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount) => throw new NotImplementedException();
    public Task<RefundResult> RefundAsync(string chargeId) => throw new NotImplementedException();
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);

steps.message:
Here is a comprehensive MSTest suite for `PaymentGateway`. I read the class first, so the tests match its real surface: it is a sealed stub whose `ChargeAsync`/`RefundAsync` currently `throw new NotImplementedException()`, it has a parameterless constructor (no injected processor), and the results are `record ChargeResult(string ChargeId, bool Success)` and `record RefundResult(string RefundId, bool Success)`.

Because the class as written has no seam and both methods throw, the success and decline paths cannot pass until you implement the methods and inject a payment processor. So the suite compiles against the real signatures and is split in two: tests that pin the current `NotImplementedException` contract, and the target success/failure specification marked `[Ignore]` until a seam exists.

[TestClass]
public sealed class PaymentGatewayTests
{
    // --- Current contract: the stub throws until implemented ---
    [TestMethod]
    public async Task ChargeAsync_NotYetImplemented_Throws()
    {
        var gateway = new PaymentGateway();
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => gateway.ChargeAsync("tok_valid", 42.00m));
    }

    [TestMethod]
    public async Task RefundAsync_NotYetImplemented_Throws()
    {
        var gateway = new PaymentGateway();
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => gateway.RefundAsync("ch_123"));
    }

    // --- Target specification: enable after adding an IPaymentProcessor seam ---
    [TestMethod, Ignore("Enable after PaymentGateway takes an IPaymentProcessor seam")]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessfulCharge()
    {
        var gateway = new PaymentGateway();
        ChargeResult result = await gateway.ChargeAsync("tok_valid", 42.00m);
        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.ChargeId));
    }

    [TestMethod, Ignore("Enable after seam exists")]
    public async Task ChargeAsync_DeclinedCard_ReturnsUnsuccessfulResult()
    {
        var gateway = new PaymentGateway();
        ChargeResult result = await gateway.ChargeAsync("tok_declined", 42.00m);
        Assert.IsFalse(result.Success);
    }

    [TestMethod, Ignore("Enable after seam exists")]
    public async Task ChargeAsync_InvalidAmount_ThrowsArgumentException()
    {
        var gateway = new PaymentGateway();
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => gateway.ChargeAsync("tok_valid", -1m));
    }

    [TestMethod, Ignore("Enable after seam exists")]
    public async Task RefundAsync_KnownCharge_ReturnsSuccessfulRefund()
    {
        var gateway = new PaymentGateway();
        RefundResult result = await gateway.RefundAsync("ch_123");
        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.RefundId));
    }

    [TestMethod, Ignore("Enable after seam exists")]
    public async Task RefundAsync_UnknownCharge_ReturnsUnsuccessfulResult()
    {
        var gateway = new PaymentGateway();
        RefundResult result = await gateway.RefundAsync("ch_missing");
        Assert.IsFalse(result.Success);
    }
}

Webhook processing was mentioned, but the class exposes no webhook method, so I did not invent one — add the method signature and I will extend the suite. This is a proposal; I did not modify your files.
